public:
    char tag_type_;
    int32_t tag_size_;
    uint32_t tag_time_;
    char *tag_data_;
    bool should_fail_;

public:
    MockFlvDecoderWithData()
    {
        tag_type_ = SrsFrameTypeScript;
        tag_size_ = 0;
        tag_time_ = 0;
        tag_data_ = NULL;
        should_fail_ = false;
    }

