    new_desc->audio_track_desc_->media_ = new SrsAudioPayload(112, "opus", 48000, 2); // Changed PT
    new_desc->audio_track_desc_->media_->pt_ = 112;
    new_desc->audio_track_desc_->red_ = new SrsRedPayload(64, "red", 48000, 2); // Changed PT
    new_desc->audio_track_desc_->red_->pt_ = 64;

    // Create new video track description with different SSRC and PT
    SrsRtcTrackDescription *new_video_desc = new SrsRtcTrackDescription();
    new_video_desc->type_ = "video";
    new_video_desc->ssrc_ = 2002;                                     // Changed SSRC
    new_video_desc->media_ = new SrsVideoPayload(103, "H264", 90000); // Changed PT
    new_video_desc->media_->pt_ = 103;
    new_video_desc->red_ = new SrsCodecPayload(101, "rtx", 90000); // Changed PT
    new_video_desc->red_->pt_ = 101;
    new_desc->video_track_descs_.push_back(new_video_desc);

    // Call on_stream_change
    play_stream->on_stream_change(new_desc.get());

    // Verify that audio track map was updated with new SSRC
    EXPECT_EQ(1, (int)play_stream->audio_tracks_.size());
    EXPECT_TRUE(play_stream->audio_tracks_.find(1001) == play_stream->audio_tracks_.end()); // Old SSRC removed
    EXPECT_TRUE(play_stream->audio_tracks_.find(1002) != play_stream->audio_tracks_.end()); // New SSRC added

    // Verify that video track map was updated with new SSRC
    EXPECT_EQ(1, (int)play_stream->video_tracks_.size());
    EXPECT_TRUE(play_stream->video_tracks_.find(2001) == play_stream->video_tracks_.end()); // Old SSRC removed
    EXPECT_TRUE(play_stream->video_tracks_.find(2002) != play_stream->video_tracks_.end()); // New SSRC added

    // Verify that the track objects are the same (not recreated)
    EXPECT_EQ(audio_track, play_stream->audio_tracks_[1002]);
    EXPECT_EQ(video_track, play_stream->video_tracks_[2002]);

    // Verify that PT values were updated
    EXPECT_EQ(112, audio_track->track_desc()->media_->pt_of_publisher_);
    EXPECT_EQ(64, audio_track->track_desc()->red_->pt_of_publisher_);
    EXPECT_EQ(103, video_track->track_desc()->media_->pt_of_publisher_);
    EXPECT_EQ(101, video_track->track_desc()->red_->pt_of_publisher_);

    // Test with NULL desc (should return early without error)
    play_stream->on_stream_change(NULL);
    EXPECT_EQ(1, (int)play_stream->audio_tracks_.size());
    EXPECT_EQ(1, (int)play_stream->video_tracks_.size());
}

// The track maps and SrsRtspConnection::networks_ sit on opposite sides of an SSRC rewrite: the maps are keyed by the
// publisher SSRC of arriving packets, while SrsRtspSendTrack::on_rtp rewrites each packet to track_desc_->ssrc_ before
// do_send_packet looks it up in networks_, which SETUP keyed from the same track description. A republish must
// therefore re-key the maps to the new publisher SSRC without touching track_desc_->ssrc_, or every packet after it
// would miss in networks_ and the client would also see its negotiated SSRC change mid-session.
//
// This test passes from the start: it locks in the current, intended behavior rather than driving a fix. Without it,
// assigning the new SSRC to track_desc_ inside on_stream_change would leave every existing test green.
VOID TEST(RtspPlayStreamTest, OnStreamChangeKeepsSubscriberSsrc)
{
    srs_error_t err = srs_success;

    MockStatisticForRtspPlayStream mock_stat;
    MockRtspSourceManager mock_rtsp_sources;
    MockAppFactoryForRtspPlayStream mock_app_factory;
    mock_rtsp_sources.mock_source_ = SrsSharedPtr<SrsRtspSource>(new SrsRtspSource());

    SrsUniquePtr<MockEdgeRequest> mock_req(new MockEdgeRequest("test.vhost", "live", "stream1"));

    SrsContextId cid;
    SrsUniquePtr<SrsRtspPlayStream> play_stream(new SrsRtspPlayStream(NULL, cid));
    play_stream->stat_ = &mock_stat;
    play_stream->rtsp_sources_ = &mock_rtsp_sources;
    play_stream->app_factory_ = &mock_app_factory;

    // SETUP negotiated SSRC 1001 for audio and 2001 for video, which is what networks_ is keyed by.
    SrsUniquePtr<SrsRtcTrackDescription> audio_desc(new SrsRtcTrackDescription());
    audio_desc->type_ = "audio";
    audio_desc->id_ = "0";
    audio_desc->ssrc_ = 1001;
    audio_desc->media_ = new SrsAudioPayload(111, "opus", 48000, 2);
    audio_desc->media_->pt_of_publisher_ = 111;

    SrsUniquePtr<SrsRtcTrackDescription> video_desc(new SrsRtcTrackDescription());
    video_desc->type_ = "video";
    video_desc->id_ = "1";
    video_desc->ssrc_ = 2001;
    video_desc->media_ = new SrsVideoPayload(102, "H264", 90000);
    video_desc->media_->pt_of_publisher_ = 102;

    std::map<uint32_t, SrsRtcTrackDescription *> sub_relations;
    sub_relations[1001] = audio_desc.get();
    sub_relations[2001] = video_desc.get();
    HELPER_EXPECT_SUCCESS(play_stream->initialize(mock_req.get(), sub_relations));

    ISrsRtspSendTrack *audio_track = play_stream->audio_tracks_[1001];
    ISrsRtspSendTrack *video_track = play_stream->video_tracks_[2001];
    EXPECT_EQ(1001, (int)audio_track->track_desc()->ssrc_);
    EXPECT_EQ(2001, (int)video_track->track_desc()->ssrc_);

    // The publisher republishes and comes back with different SSRCs.
    SrsUniquePtr<SrsRtcSourceDescription> new_desc(new SrsRtcSourceDescription());
    new_desc->audio_track_desc_ = new SrsRtcTrackDescription();
    new_desc->audio_track_desc_->type_ = "audio";
    new_desc->audio_track_desc_->ssrc_ = 1002;
    new_desc->audio_track_desc_->media_ = new SrsAudioPayload(112, "opus", 48000, 2);
    new_desc->audio_track_desc_->media_->pt_ = 112;

    SrsRtcTrackDescription *new_video_desc = new SrsRtcTrackDescription();
    new_video_desc->type_ = "video";
    new_video_desc->ssrc_ = 2002;
    new_video_desc->media_ = new SrsVideoPayload(103, "H264", 90000);
    new_video_desc->media_->pt_ = 103;
    new_desc->video_track_descs_.push_back(new_video_desc);

    play_stream->on_stream_change(new_desc.get());

    // The input side follows the publisher, so arriving packets still find their track.
    EXPECT_TRUE(play_stream->audio_tracks_.find(1002) != play_stream->audio_tracks_.end());
    EXPECT_TRUE(play_stream->video_tracks_.find(2002) != play_stream->video_tracks_.end());

    // GOAL: the output side does not move. These SSRCs are what on_rtp stamps onto every outgoing
    // packet and what SrsRtspConnection::networks_ is keyed by, so they must survive the republish.
    EXPECT_EQ(1001, (int)audio_track->track_desc()->ssrc_);
    EXPECT_EQ(2001, (int)video_track->track_desc()->ssrc_);
}

// A republish brings new SSRCs: on_stream_change re-keys the track maps, so it must also clear the fast cache, or the
// slots keep the old SSRCs and every packet of the new stream misses the cache for the rest of the session.
VOID TEST(RtspPlayStreamTest, OnStreamChangeResetsTrackCache)
{
    srs_error_t err = srs_success;

    MockRtspConnection mock_session;
    MockStatisticForRtspPlayStream mock_stat;
    MockRtspSourceManager mock_rtsp_sources;
    MockAppFactoryForRtspPlayStream mock_app_factory;
    mock_rtsp_sources.mock_source_ = SrsSharedPtr<SrsRtspSource>(new SrsRtspSource());
    SrsUniquePtr<MockEdgeRequest> mock_req(new MockEdgeRequest("test.vhost", "live", "stream1"));

    SrsContextId cid;
    SrsUniquePtr<SrsRtspPlayStream> play_stream(new SrsRtspPlayStream(&mock_session, cid));
    play_stream->stat_ = &mock_stat;
    play_stream->rtsp_sources_ = &mock_rtsp_sources;
    play_stream->app_factory_ = &mock_app_factory;

    // The first publisher: audio 1001 and video 2001.
    SrsUniquePtr<SrsRtcTrackDescription> audio_desc(new SrsRtcTrackDescription());
    audio_desc->type_ = "audio";
    audio_desc->id_ = "audio_track";
    audio_desc->ssrc_ = 1001;
    audio_desc->media_ = new SrsAudioPayload(111, "opus", 48000, 2);
    SrsUniquePtr<SrsRtcTrackDescription> video_desc(new SrsRtcTrackDescription());
    video_desc->type_ = "video";
    video_desc->id_ = "video_track";
    video_desc->ssrc_ = 2001;
    video_desc->media_ = new SrsVideoPayload(102, "H264", 90000);

    std::map<uint32_t, SrsRtcTrackDescription *> sub_relations;
    sub_relations[1001] = audio_desc.get();
    sub_relations[2001] = video_desc.get();
    HELPER_EXPECT_SUCCESS(play_stream->initialize(mock_req.get(), sub_relations));

    // One packet per SSRC fills two slots.
    if (true) {
        SrsUniquePtr<SrsRtpPacket> audio_pkt(new SrsRtpPacket());
        audio_pkt->header_.set_ssrc(1001);
        audio_pkt->header_.set_sequence(100);
        audio_pkt->frame_type_ = SrsFrameTypeAudio;
        SrsRtpPacket *audio_pkt_ptr = audio_pkt.get();
        HELPER_EXPECT_SUCCESS(play_stream->send_packet(audio_pkt_ptr));

        SrsUniquePtr<SrsRtpPacket> video_pkt(new SrsRtpPacket());
        video_pkt->header_.set_ssrc(2001);
        video_pkt->header_.set_sequence(200);
        video_pkt->frame_type_ = SrsFrameTypeVideo;
        SrsRtpPacket *video_pkt_ptr = video_pkt.get();
        HELPER_EXPECT_SUCCESS(play_stream->send_packet(video_pkt_ptr));
    }
    EXPECT_EQ(1001u, play_stream->cache_ssrc0_);
    EXPECT_EQ(2001u, play_stream->cache_ssrc1_);

    // The publisher republishes with new SSRCs.
    SrsUniquePtr<SrsRtcSourceDescription> new_desc(new SrsRtcSourceDescription());
    SrsRtcTrackDescription *new_audio_desc = new SrsRtcTrackDescription();
    new_audio_desc->type_ = "audio";
    new_audio_desc->ssrc_ = 1002;
    new_audio_desc->media_ = new SrsAudioPayload(111, "opus", 48000, 2);
    new_desc->audio_track_desc_ = new_audio_desc;
    SrsRtcTrackDescription *new_video_desc = new SrsRtcTrackDescription();
    new_video_desc->type_ = "video";
    new_video_desc->ssrc_ = 2002;
    new_video_desc->media_ = new SrsVideoPayload(102, "H264", 90000);
    new_desc->video_track_descs_.push_back(new_video_desc);
    play_stream->on_stream_change(new_desc.get());

    // The cache starts over, so nothing routes by the old SSRCs.
    EXPECT_EQ(0u, play_stream->cache_ssrc0_);
    EXPECT_EQ(0u, play_stream->cache_ssrc1_);
    EXPECT_EQ(0u, play_stream->cache_ssrc2_);
    EXPECT_TRUE(play_stream->cache_track0_ == NULL);
    EXPECT_TRUE(play_stream->cache_track1_ == NULL);

    // The first packet of the new stream takes the first slot again.
    MockRtspSendTrack *video_track = dynamic_cast<MockRtspSendTrack *>(play_stream->video_tracks_[2002]);
    ASSERT_TRUE(video_track != NULL);
    video_track->reset();
    SrsUniquePtr<SrsRtpPacket> pkt(new SrsRtpPacket());
    pkt->header_.set_ssrc(2002);
    pkt->header_.set_sequence(201);
    pkt->frame_type_ = SrsFrameTypeVideo;
    SrsRtpPacket *pkt_ptr = pkt.get();
    HELPER_EXPECT_SUCCESS(play_stream->send_packet(pkt_ptr));
    EXPECT_EQ(1, video_track->on_rtp_count_);
    EXPECT_EQ(2002u, play_stream->cache_ssrc0_);
    EXPECT_EQ(video_track, play_stream->cache_track0_);
    EXPECT_EQ(0u, play_stream->cache_ssrc1_);
}

// A republish makes a new RTP builder, which sets each track of the source with a new SSRC from the stream's first
// audio and video, after the source's on_publish. A player that stays across the republish must follow those SSRCs,
// or it drops every packet of the new publish.
VOID TEST(RtspPlayStreamTest, RepublishTracksRekeyPlayer)
{
    srs_error_t err = srs_success;

    MockRtspConnection mock_session;
    MockStatisticForRtspPlayStream mock_stat;
    MockRtspSourceManager mock_rtsp_sources;
    MockAppFactoryForRtspPlayStream mock_app_factory;
    mock_rtsp_sources.mock_source_ = SrsSharedPtr<SrsRtspSource>(new SrsRtspSource());
    SrsUniquePtr<MockEdgeRequest> mock_req(new MockEdgeRequest("test.vhost", "live", "stream1"));

    SrsSharedPtr<SrsRtspSource> source(new SrsRtspSource());
    HELPER_EXPECT_SUCCESS(source->initialize(mock_req.get()));

    // The first publish sets audio 1001 and video 2001, before the player comes.
    SrsUniquePtr<SrsRtcTrackDescription> audio_desc(new SrsRtcTrackDescription());
    audio_desc->type_ = "audio";
    audio_desc->id_ = "audio_track";
    audio_desc->ssrc_ = 1001;
    audio_desc->media_ = new SrsAudioPayload(97, "MPEG4-GENERIC", 44100, 2);
    SrsUniquePtr<SrsRtcTrackDescription> video_desc(new SrsRtcTrackDescription());
    video_desc->type_ = "video";
    video_desc->id_ = "video_track";
    video_desc->ssrc_ = 2001;
    video_desc->media_ = new SrsVideoPayload(96, "H264", 90000);
    source->set_audio_desc(audio_desc.get());
    source->set_video_desc(video_desc.get());

    // The player sets up both tracks and consumes the source.
    SrsContextId cid;
    SrsUniquePtr<SrsRtspPlayStream> play_stream(new SrsRtspPlayStream(&mock_session, cid));
    play_stream->stat_ = &mock_stat;
    play_stream->rtsp_sources_ = &mock_rtsp_sources;
    play_stream->app_factory_ = &mock_app_factory;

    std::map<uint32_t, SrsRtcTrackDescription *> sub_relations;
    sub_relations[1001] = audio_desc.get();
    sub_relations[2001] = video_desc.get();
    HELPER_EXPECT_SUCCESS(play_stream->initialize(mock_req.get(), sub_relations));

    SrsRtspConsumer *consumer_raw = NULL;
    HELPER_EXPECT_SUCCESS(source->create_consumer(consumer_raw));
    SrsUniquePtr<SrsRtspConsumer> consumer(consumer_raw);
    consumer->set_handler(play_stream.get());

    // The republish's builder sets the tracks with audio 1002 and video 2002.
    SrsUniquePtr<SrsRtcTrackDescription> new_audio_desc(audio_desc->copy());
    new_audio_desc->ssrc_ = 1002;
    SrsUniquePtr<SrsRtcTrackDescription> new_video_desc(video_desc->copy());
    new_video_desc->ssrc_ = 2002;
    source->set_audio_desc(new_audio_desc.get());
    source->set_video_desc(new_video_desc.get());

    // The player plays the new publish's packets.
    MockRtspSendTrack *audio_track = dynamic_cast<MockRtspSendTrack *>(play_stream->audio_tracks_[1002]);
    MockRtspSendTrack *video_track = dynamic_cast<MockRtspSendTrack *>(play_stream->video_tracks_[2002]);
    ASSERT_TRUE(audio_track != NULL);
    ASSERT_TRUE(video_track != NULL);
    EXPECT_EQ(1, (int)play_stream->audio_tracks_.size());
    EXPECT_EQ(1, (int)play_stream->video_tracks_.size());

    SrsUniquePtr<SrsRtpPacket> audio_pkt(new SrsRtpPacket());
    audio_pkt->header_.set_ssrc(1002);
    audio_pkt->frame_type_ = SrsFrameTypeAudio;
    SrsRtpPacket *audio_pkt_ptr = audio_pkt.get();
    HELPER_EXPECT_SUCCESS(play_stream->send_packet(audio_pkt_ptr));
    EXPECT_EQ(1, audio_track->on_rtp_count_);

    SrsUniquePtr<SrsRtpPacket> video_pkt(new SrsRtpPacket());
    video_pkt->header_.set_ssrc(2002);
    video_pkt->frame_type_ = SrsFrameTypeVideo;
    SrsRtpPacket *video_pkt_ptr = video_pkt.get();
    HELPER_EXPECT_SUCCESS(play_stream->send_packet(video_pkt_ptr));
    EXPECT_EQ(1, video_track->on_rtp_count_);
}

