// A method SRS doesn't serve, such as the GET_PARAMETER keep-alive, is answered 501 Not Implemented
// (RFC 2326), so the client doesn't wait for an answer until its timeout. The connection serves the
// next request, and a player it has plays on.
VOID TEST(RtspConnectionTest, UnsupportedMethodIsAnswered)
{
    srs_error_t err = srs_success;

    MockRtspStack *mock_rtsp = new MockRtspStack();
    SrsUniquePtr<SrsRtspConnection> conn(new SrsRtspConnection(NULL, NULL, "127.0.0.1", 8554));
    conn->rtsp_ = mock_rtsp;

    // Before any DESCRIBE, there is no session to name.
    if (true) {
        SrsRtspRequest *req = new SrsRtspRequest();
        req->method_ = "GET_PARAMETER";
        req->uri_ = "rtsp://127.0.0.1:8554/live/stream";
        req->seq_ = 1;
        mock_rtsp->reset();
        HELPER_EXPECT_SUCCESS(conn->on_rtsp_request(req));
        EXPECT_TRUE(mock_rtsp->send_message_called_);
        EXPECT_EQ(1, mock_rtsp->last_response_seq_);
        EXPECT_EQ(SRS_CONSTS_RTSP_NotImplemented, mock_rtsp->last_response_status_);
        EXPECT_TRUE(mock_rtsp->last_response_session_.empty());
    }

    // While playing: the answer names the session, and the player isn't stopped.
    conn->session_id_ = "test_session_123";
    MockRtspPlayStream *player = new MockRtspPlayStream();
    conn->player_ = player;

    const char *methods[] = {"GET_PARAMETER", "SET_PARAMETER", "PAUSE", "RECORD", "ANNOUNCE", "REDIRECT", "FOO"};
    for (int i = 0; i < (int)(sizeof(methods) / sizeof(methods[0])); i++) {
        SrsRtspRequest *req = new SrsRtspRequest();
        req->method_ = methods[i];
        req->uri_ = "rtsp://127.0.0.1:8554/live/stream";
        req->seq_ = 10 + i;
        mock_rtsp->reset();
        HELPER_EXPECT_SUCCESS(conn->on_rtsp_request(req));
        EXPECT_TRUE(mock_rtsp->send_message_called_) << methods[i];
        EXPECT_EQ(10 + i, mock_rtsp->last_response_seq_) << methods[i];
        EXPECT_EQ(SRS_CONSTS_RTSP_NotImplemented, mock_rtsp->last_response_status_) << methods[i];
        EXPECT_STREQ("test_session_123", mock_rtsp->last_response_session_.c_str()) << methods[i];
        EXPECT_TRUE(player == conn->player_) << methods[i];
        EXPECT_FALSE(player->stop_called_) << methods[i];
    }

    // The connection serves the next request.
    if (true) {
        SrsRtspRequest *req = new SrsRtspRequest();
        req->method_ = "OPTIONS";
        req->uri_ = "rtsp://127.0.0.1:8554/live/stream";
        req->seq_ = 20;
        mock_rtsp->reset();
        HELPER_EXPECT_SUCCESS(conn->on_rtsp_request(req));
        EXPECT_EQ(20, mock_rtsp->last_response_seq_);
        EXPECT_EQ(SRS_CONSTS_RTSP_OK, mock_rtsp->last_response_status_);
    }

    // An answer that can't be sent ends the connection, as for the other methods.
    if (true) {
        SrsRtspRequest *req = new SrsRtspRequest();
        req->method_ = "GET_PARAMETER";
        req->uri_ = "rtsp://127.0.0.1:8554/live/stream";
        req->seq_ = 21;
        mock_rtsp->reset();
        mock_rtsp->send_message_error_ = srs_error_new(ERROR_SOCKET_WRITE, "write");
        HELPER_EXPECT_FAILED(conn->on_rtsp_request(req));
        EXPECT_FALSE(player->stop_called_);
    }

    conn->rtsp_ = NULL;
    srs_freep(mock_rtsp);
}

// The listener hands the connection the client's socket, and nothing else frees it, so the
// connection must: freeing it closes the TCP connection. Otherwise a client whose session SRS ended,
// on a request it can't parse or a DELETE through the API, waits for the close forever, and SRS
// keeps the socket. The TCP network a SETUP made writes to the same socket and doesn't own it.
VOID TEST(RtspConnectionTest, DestructorFreesSocket)
{
    // A connection that served no request.
    if (true) {
        bool destroyed = false;
        SrsRtspConnection *conn = new SrsRtspConnection(NULL, new MockSocketForRtspConn(&destroyed), "127.0.0.1", 8554);
        EXPECT_FALSE(destroyed);
        srs_freep(conn);
        EXPECT_TRUE(destroyed);
    }

    // A connection with a TCP network on the socket: the socket is freed once, after the network.
    if (true) {
        bool destroyed = false;
        SrsRtspConnection *conn = new SrsRtspConnection(NULL, new MockSocketForRtspConn(&destroyed), "127.0.0.1", 8554);
        conn->networks_[1001] = new SrsRtspTcpNetwork(conn->skt_, 0);
        srs_freep(conn);
        EXPECT_TRUE(destroyed);
    }
}

// RTSP has no session state machine: on_rtsp_request dispatches each request on its own, so a
// client may send DESCRIBE more than once. Each DESCRIBE rebuilds the SDP from the source, so the
// track descriptions it stores must be rebuilt with it, not silently discarded.
VOID TEST(RtspConnectionTest, RepeatedDescribeReplacesTrackDescriptions)
{
    srs_error_t err = srs_success;

    MockEdgeConfig mock_config;
    MockSecurity mock_security;
    MockHttpHooks mock_hooks;
    MockRtspSourceManager mock_rtsp_sources;

    SrsSharedPtr<SrsRtspSource> mock_source(new SrsRtspSource());

    SrsRtcTrackDescription *audio_desc = new SrsRtcTrackDescription();
    audio_desc->type_ = "audio";
    audio_desc->ssrc_ = 1001;
    audio_desc->media_ = new SrsAudioPayload(97, "MPEG4-GENERIC", 48000, 2);
    mock_source->audio_desc_ = audio_desc;

    mock_rtsp_sources.mock_source_ = mock_source;

    SrsUniquePtr<SrsRtspConnection> conn(new SrsRtspConnection(NULL, NULL, "127.0.0.1", 8554));
    conn->config_ = &mock_config;
    conn->security_ = &mock_security;
    conn->hooks_ = &mock_hooks;
    conn->rtsp_sources_ = &mock_rtsp_sources;

    SrsUniquePtr<SrsRtspRequest> req(new SrsRtspRequest());
    req->uri_ = "rtsp://127.0.0.1:8554/live/stream";

    std::string sdp;
    HELPER_EXPECT_SUCCESS(conn->do_describe(req.get(), sdp));
    EXPECT_EQ(1, (int)conn->tracks_.size());
    EXPECT_EQ(97, conn->tracks_[1001]->media_->pt_);

    // The publisher re-negotiates its payload type, so a second DESCRIBE must report the new one.
    audio_desc->media_->pt_ = 98;

    sdp = "";
    HELPER_EXPECT_SUCCESS(conn->do_describe(req.get(), sdp));

    // GOAL: the stored description is the one this DESCRIBE built. std::map::insert keeps the
    // existing entry and drops the new copy on the floor, which both leaks it and serves stale
    // payload types to the client.
    EXPECT_EQ(1, (int)conn->tracks_.size());
    EXPECT_EQ(98, conn->tracks_[1001]->media_->pt_);

    // Clean up injected mocks to avoid double-free
    conn->config_ = NULL;
    conn->security_ = NULL;
    conn->hooks_ = NULL;
    conn->rtsp_sources_ = NULL;
}

// A publisher that republishes between two DESCRIBEs comes back with a new SSRC. The stale track
// must go, because track ids restart at 0 on every DESCRIBE and SETUP resolves a stream id by
// scanning for the first matching id.
VOID TEST(RtspConnectionTest, RepeatedDescribeAfterSsrcChangeDropsStaleTracks)
{
    srs_error_t err = srs_success;

    MockEdgeConfig mock_config;
    MockSecurity mock_security;
    MockHttpHooks mock_hooks;
    MockRtspSourceManager mock_rtsp_sources;

    SrsSharedPtr<SrsRtspSource> mock_source(new SrsRtspSource());

    SrsRtcTrackDescription *audio_desc = new SrsRtcTrackDescription();
    audio_desc->type_ = "audio";
    audio_desc->ssrc_ = 1001;
    audio_desc->media_ = new SrsAudioPayload(97, "MPEG4-GENERIC", 48000, 2);
    mock_source->audio_desc_ = audio_desc;

    mock_rtsp_sources.mock_source_ = mock_source;

    SrsUniquePtr<SrsRtspConnection> conn(new SrsRtspConnection(NULL, NULL, "127.0.0.1", 8554));
    conn->config_ = &mock_config;
    conn->security_ = &mock_security;
    conn->hooks_ = &mock_hooks;
    conn->rtsp_sources_ = &mock_rtsp_sources;

    SrsUniquePtr<SrsRtspRequest> req(new SrsRtspRequest());
    req->uri_ = "rtsp://127.0.0.1:8554/live/stream";

    std::string sdp;
    HELPER_EXPECT_SUCCESS(conn->do_describe(req.get(), sdp));

    // The publisher restarts and comes back with a different SSRC.
    audio_desc->ssrc_ = 1002;

    sdp = "";
    HELPER_EXPECT_SUCCESS(conn->do_describe(req.get(), sdp));

    // GOAL: only the live track survives, so trackID=0 resolves to the SSRC now being published.
    // Keeping both leaves two tracks carrying id_ "0", and the scan returns whichever sorts first.
    EXPECT_EQ(1, (int)conn->tracks_.size());
    EXPECT_TRUE(conn->tracks_.find(1002) != conn->tracks_.end());

    uint32_t ssrc = 0;
    HELPER_EXPECT_SUCCESS(conn->get_ssrc_by_stream_id(0, &ssrc));
    EXPECT_EQ(1002, (int)ssrc);

    // Clean up injected mocks to avoid double-free
    conn->config_ = NULL;
    conn->security_ = NULL;
    conn->hooks_ = NULL;
    conn->rtsp_sources_ = NULL;
}

// RTSP allows a client to re-SETUP a track, for instance to move it to another interleaved channel.
// The writer installed by the previous SETUP is owned by the connection, so replacing it must free
// it; otherwise each repeat leaks one until the connection ends.
VOID TEST(RtspConnectionTest, RepeatedSetupFreesPreviousNetwork)
{
    srs_error_t err = srs_success;

    SrsUniquePtr<SrsRtspConnection> conn(new SrsRtspConnection(NULL, NULL, "127.0.0.1", 8554));

    SrsRtcTrackDescription *video_desc = new SrsRtcTrackDescription();
    video_desc->type_ = "video";
    video_desc->id_ = "0";
    video_desc->ssrc_ = 12345;
    conn->tracks_[12345] = video_desc;

    // Stand in for the writer a previous SETUP installed, so its destruction is observable.
    bool destroyed = false;
    conn->networks_[12345] = new MockStreamWriterForRtspConn(&destroyed);

    SrsUniquePtr<SrsRtspRequest> req(new SrsRtspRequest());
    req->method_ = "SETUP";
    req->stream_id_ = 0;
    req->transport_ = new SrsRtspTransport();
    req->transport_->transport_ = "RTP";
    req->transport_->profile_ = "AVP";
    req->transport_->lower_transport_ = "TCP";
    req->transport_->interleaved_min_ = 2;
    req->transport_->interleaved_max_ = 3;

    uint32_t ssrc = 0;
    HELPER_EXPECT_SUCCESS(conn->do_setup(req.get(), &ssrc));

    // GOAL: the replaced writer is freed, and the slot holds exactly one writer.
    EXPECT_TRUE(destroyed);
    EXPECT_EQ(1, (int)conn->networks_.size());

    ISrsStreamWriter *network = conn->networks_[12345];
    srs_freep(network);
    conn->networks_.clear();
}

// The connection keeps reading requests while its player sends, and a send to a slow client yields
// inside the writer of the track, between the interleaved header and the payload. A SETUP of that
// track in this state would replace the writer the player is still in, so it is not valid while a
// player plays (RFC 2326, 455 Method Not Valid in This State), as DESCRIBE is not.
VOID TEST(RtspConnectionTest, SetupWhilePlayingIsRefused)
{
    srs_error_t err = srs_success;

    MockBlockingSocketForRtspConn *skt = new MockBlockingSocketForRtspConn();
    SrsUniquePtr<SrsRtspConnection> conn(new SrsRtspConnection(NULL, skt, "127.0.0.1", 8554));

    MockRtspStack *mock_rtsp = new MockRtspStack();
    srs_freep(conn->rtsp_);
    conn->rtsp_ = mock_rtsp;
    conn->session_id_ = "session1";

    SrsRtcTrackDescription *video_desc = new SrsRtcTrackDescription();
    video_desc->type_ = "video";
    video_desc->id_ = "0";
    video_desc->ssrc_ = 12345;
    conn->tracks_[12345] = video_desc;

    SrsRtspRequest *req = new SrsRtspRequest();
    req->method_ = "SETUP";
    req->seq_ = 2;
    req->stream_id_ = 0;
    req->transport_ = new SrsRtspTransport();
    req->transport_->transport_ = "RTP";
    req->transport_->profile_ = "AVP";
    req->transport_->lower_transport_ = "TCP";
    req->transport_->interleaved_min_ = 0;
    req->transport_->interleaved_max_ = 1;
    HELPER_EXPECT_SUCCESS(conn->on_rtsp_request(req));
    EXPECT_EQ(SRS_CONSTS_RTSP_OK, mock_rtsp->last_response_status_);
    ISrsStreamWriter *network = conn->networks_[12345];
    ASSERT_TRUE(network != NULL);

    // What PLAY makes, then the player sends a packet and the client stops reading.
    conn->player_ = new MockRtspPlayStream();

    SrsUniquePtr<SrsRtpPacket> pkt(new SrsRtpPacket());
    pkt->header_.set_ssrc(12345);
    MockRtspSenderForRtspConn sender(conn.get(), pkt.get());
    SrsUniquePtr<SrsSTCoroutine> trd(new SrsSTCoroutine("rtsp_sender", &sender));

    skt->hold_ = true;
    HELPER_EXPECT_SUCCESS(trd->start());
    while (skt->write_count_ == 0) {
        srs_usleep(1 * SRS_UTIME_MILLISECONDS);
    }

    // A SETUP of the same track to another channel, while the player is inside its writer.
    req = new SrsRtspRequest();
    req->method_ = "SETUP";
    req->seq_ = 3;
    req->stream_id_ = 0;
    req->transport_ = new SrsRtspTransport();
    req->transport_->transport_ = "RTP";
    req->transport_->profile_ = "AVP";
    req->transport_->lower_transport_ = "TCP";
    req->transport_->interleaved_min_ = 2;
    req->transport_->interleaved_max_ = 3;
    mock_rtsp->reset();
    HELPER_EXPECT_SUCCESS(conn->on_rtsp_request(req));

    // GOAL: the SETUP is refused with the session, and the writer of the track stays.
    EXPECT_TRUE(mock_rtsp->send_message_called_);
    EXPECT_EQ(3, mock_rtsp->last_response_seq_);
    EXPECT_EQ(SRS_CONSTS_RTSP_MethodNotValidInThisState, mock_rtsp->last_response_status_);
    EXPECT_STREQ("session1", mock_rtsp->last_response_session_.c_str());
    EXPECT_TRUE(conn->networks_[12345] == network);

    // GOAL: the client reads again, and the player finishes the packet on the channel it was set up on.
    skt->hold_ = false;
    while (!sender.done_) {
        srs_usleep(1 * SRS_UTIME_MILLISECONDS);
    }
    HELPER_EXPECT_SUCCESS(srs_error_copy(sender.err_));
    EXPECT_EQ(2, skt->write_count_);
    ASSERT_EQ(1, (int)skt->channels_.size());
    EXPECT_EQ(0, skt->channels_[0]);
}

// do_send_packet runs for every RTP packet. A lookup miss must not modify the map: std::map's
// operator[] default-inserts a NULL entry, which allocates a node on the send path.
VOID TEST(RtspConnectionTest, SendPacketDoesNotInsertOnLookupMiss)
{
    SrsUniquePtr<SrsRtspConnection> conn(new SrsRtspConnection(NULL, NULL, "127.0.0.1", 8554));

    SrsUniquePtr<SrsRtpPacket> pkt(new SrsRtpPacket());
    pkt->header_.set_ssrc(4242);

    // GOAL: an unknown SSRC is reported, and the map is left alone.
    srs_error_t err = conn->do_send_packet(pkt.get());
    EXPECT_TRUE(err != srs_success);
    EXPECT_EQ(ERROR_RTSP_NO_TRACK, srs_error_code(err));
    srs_freep(err);

    EXPECT_EQ(0, (int)conn->networks_.size());
}

