ISrsRtcPacketSender::ISrsRtcPacketSender()
{
}

ISrsRtcPacketSender::~ISrsRtcPacketSender()
{
}

SrsRtcSendTrack::SrsRtcSendTrack(ISrsRtcPacketSender *sender, SrsRtcTrackDescription *track_desc, bool is_audio)
{
    sender_ = sender;
    track_desc_ = track_desc->copy();
    nack_no_copy_ = false;
    keep_original_ssrc_ = false;

    // Make a different start of sequence number, for debugging.
    jitter_ts_ = new SrsRtcTsJitter(track_desc_->type_ == "audio" ? 10000 : 20000);
    jitter_seq_ = new SrsRtcSeqJitter(track_desc_->type_ == "audio" ? 100 : 200);

    if (is_audio) {
        rtp_queue_ = new SrsRtpRingBuffer(100);
    } else {
        rtp_queue_ = new SrsRtpRingBuffer(1000);
    }

    nack_epp = new SrsErrorPithyPrint();

    rtx_seq_ = 0;
    rand_ = new SrsRand();

    sender_info_ = new SrsRtcSenderInfo();
}

void SrsRtcSendTrack::assemble()
{
    // The RTX sequence space starts at a random point, like a fresh RTP stream, RFC 3550 section 5.1.
    rtx_seq_ = (uint16_t)rand_->integer();
}

SrsRtcSendTrack::~SrsRtcSendTrack()
{
    srs_freep(rtp_queue_);
    srs_freep(track_desc_);
    srs_freep(nack_epp);
    srs_freep(jitter_ts_);
    srs_freep(jitter_seq_);
    srs_freep(rand_);
    srs_freep(sender_info_);
}

bool SrsRtcSendTrack::has_ssrc(uint32_t ssrc)
{
    return track_desc_->has_ssrc(ssrc);
}

SrsRtpPacket *SrsRtcSendTrack::fetch_rtp_packet(uint16_t seq)
{
    SrsRtpPacket *pkt = rtp_queue_->at(seq);

    if (pkt == NULL) {
        return pkt;
    }

    // For NACK, it sequence must match exactly, or it cause SRTP fail.
    // Return packet only when sequence is equal.
    if (pkt->header_.get_sequence() == seq) {
        ++_srs_pps_rhnack->sugar_;
        return pkt;
    }
    ++_srs_pps_rmnack->sugar_;

    // Ignore if sequence not match.
    uint32_t nn = 0;
    if (nack_epp->can_print(pkt->header_.get_ssrc(), &nn)) {
        srs_trace("RTC: NACK miss seq=%u, require_seq=%u, ssrc=%u, ts=%u, count=%u/%u, %d bytes", seq, pkt->header_.get_sequence(),
                  pkt->header_.get_ssrc(), pkt->header_.get_timestamp(), nn, nack_epp->nn_count_, pkt->nb_bytes());
    }
    return NULL;
}

// TODO: FIXME: Should refine logs, set tracks in a time.
bool SrsRtcSendTrack::set_track_status(bool active)
{
    bool previous_status = track_desc_->is_active_;
    track_desc_->is_active_ = active;
    return previous_status;
}

bool SrsRtcSendTrack::get_track_status()
{
    return track_desc_->is_active_;
}

std::string SrsRtcSendTrack::get_track_id()
{
    return track_desc_->id_;
}

void SrsRtcSendTrack::rebuild_packet(SrsRtpPacket *pkt)
{
    // If keep_original_ssrc is enabled, skip rebuilding sequence number and timestamp.
    // This preserves the original SSRC and timestamps for end-to-end debugging.
    // @see https://github.com/ossrs/srs/issues/3850
    if (keep_original_ssrc_) {
        return;
    }

    // Rebuild the sequence number.
    int16_t seq = pkt->header_.get_sequence();
    pkt->header_.set_sequence(jitter_seq_->correct(seq));

    // Rebuild the timestamp.
    uint32_t ts = pkt->header_.get_timestamp();
    pkt->header_.set_timestamp(jitter_ts_->correct(ts));

    srs_info("RTC: Correct %s seq=%u/%u, ts=%u/%u", track_desc_->type_.c_str(), seq, pkt->header_.get_sequence(), ts, pkt->header_.get_timestamp());
}

srs_error_t SrsRtcSendTrack::send_rtcp_sr()
{
    srs_error_t err = srs_success;

    SrsRtcpSR sr;
    if (!sender_info_->fill(&sr)) {
        return err;
    }
    sr.set_ssrc(track_desc_->ssrc_);

    // The buffer has room for the SRTP trailer that the sender adds.
    char buf[kRtpPacketSize];
    SrsBuffer stream(buf, sizeof(buf));
    if ((err = sr.encode(&stream)) != srs_success) {
        return srs_error_wrap(err, "encode sr");
    }

    if ((err = sender_->send_rtcp(stream.data(), stream.pos())) != srs_success) {
        return srs_error_wrap(err, "send sr, ssrc=%u", track_desc_->ssrc_);
    }

    return err;
}

srs_error_t SrsRtcSendTrack::on_nack(SrsRtpPacket **ppkt)
{
    srs_error_t err = srs_success;

    SrsRtpPacket *pkt = *ppkt;
    uint16_t seq = pkt->header_.get_sequence();

    // insert into video_queue and audio_queue
    // We directly use the pkt, never copy it, so we should set the pkt to NULL.
    if (nack_no_copy_) {
        rtp_queue_->set(seq, pkt);
        *ppkt = NULL;
    } else {
        rtp_queue_->set(seq, pkt->copy());
    }

    return err;
}

srs_error_t SrsRtcSendTrack::on_recv_nack(const vector<uint16_t> &lost_seqs)
{
    srs_error_t err = srs_success;

    ++_srs_pps_rnack2->sugar_;

    for (int i = 0; i < (int)lost_seqs.size(); ++i) {
        uint16_t seq = lost_seqs.at(i);
        SrsRtpPacket *pkt = fetch_rtp_packet(seq);
        if (pkt == NULL) {
#ifdef SRS_NACK_DEBUG_LOG_ENABLED
            srs_trace("NACK: miss seq=%u, ssrc=%u, not in cache", seq, track_desc_->ssrc_);
#endif
            continue;
        }

        uint32_t nn = 0;
        if (nack_epp->can_print(pkt->header_.get_ssrc(), &nn)) {
            srs_trace("RTC: NACK ARQ seq=%u, ssrc=%u, ts=%u, count=%u/%u, %d bytes", pkt->header_.get_sequence(),
                      pkt->header_.get_ssrc(), pkt->header_.get_timestamp(), nn, nack_epp->nn_count_, pkt->nb_bytes());
        }

        // With RTX negotiated, answer with an RTX packet instead, RFC 4588 section 4: a copy of the header on the RTX
        // SSRC, payload type and sequence, attached to a payloader that references the cached payload without owning
        // it, so the cache is never mutated and later NACKs, plain or RTX, still see the original packet.
        if (track_desc_->rtx_ && track_desc_->rtx_ssrc_) {
            SrsRtpPacket rtx;
            rtx.header_ = pkt->header_;
            rtx.header_.set_ssrc(track_desc_->rtx_ssrc_);
            rtx.header_.set_payload_type(track_desc_->rtx_->pt_);
            rtx.header_.set_sequence(rtx_seq_++);

            SrsRtpRtxPayload *payload = new SrsRtpRtxPayload();
            payload->osn_ = pkt->header_.get_sequence();
            payload->payload_ = pkt->payload() ? pkt->payload()->copy() : NULL;
            // The payload type tag only classifies a decoded payload, such as FU-A or STAP, and nothing reads
            // it for a packet built to send, so Unknown, the default, is enough for the RTX payload.
            rtx.set_payload(payload, SrsRtpPacketPayloadTypeUnknown);

            ++_srs_pps_srtx->sugar_;
#ifdef SRS_NACK_DEBUG_LOG_ENABLED
            srs_trace("NACK: resend RTX seq=%u, ssrc=%u, pt=%u, osn=%u, media ssrc=%u, pt=%u, ts=%u, %d bytes", rtx.header_.get_sequence(),
                      track_desc_->rtx_ssrc_, (uint32_t)track_desc_->rtx_->pt_, pkt->header_.get_sequence(), pkt->header_.get_ssrc(),
                      (uint32_t)pkt->header_.get_payload_type(), pkt->header_.get_timestamp(), (int)rtx.nb_bytes());
#endif
            if ((err = sender_->do_send_packet(&rtx)) != srs_success) {
                return srs_error_wrap(err, "rtx send");
            }
            continue;
        }

        // By default, we send packets by sendmmsg.
#ifdef SRS_NACK_DEBUG_LOG_ENABLED
        srs_trace("NACK: resend plain seq=%u, ssrc=%u, pt=%u, ts=%u, %d bytes", pkt->header_.get_sequence(), pkt->header_.get_ssrc(),
                  (uint32_t)pkt->header_.get_payload_type(), pkt->header_.get_timestamp(), (int)pkt->nb_bytes());
#endif
        if ((err = sender_->do_send_packet(pkt)) != srs_success) {
            return srs_error_wrap(err, "raw send");
        }
    }

    return err;
}

    virtual ~ISrsRtcPacketSender();

public:
    virtual srs_error_t do_send_packet(SrsRtpPacket *pkt) = 0;
    // Send an RTCP packet; the buffer must have room for the SRTP trailer, see kRtpPacketSize.
    virtual srs_error_t send_rtcp(char *data, int nb_data) = 0;
};

