SrsRtspConsumer::~SrsRtspConsumer()
{
    source_->on_consumer_destroy(this);

    vector<SrsRtpPacket *>::iterator it;
    for (it = queue_.begin(); it != queue_.end(); ++it) {
        SrsRtpPacket *pkt = *it;
        srs_freep(pkt);
    }

