	for _, t := range p.Tracks {
		t := t
		p.client.OnPacketRTP(t.Media, t.Format, func(pkt *rtp.Packet) { p.add(t, pkt) })
	}
	if _, err := p.client.Play(nil); err != nil {
		return statusError("PLAY", err)
	}
	return nil
