1042	srs_error_t SrsRtspConnection::do_teardown()
1043	{
1044	    // Stop the player first, so it sends nothing after its on_stop, but free it after, so the
1045	    // on_stop still counts it in the stream's clients, as every other player's does.
1046	    if (player_) {
1047	        player_->stop();
1048	    }
1049	
1050	    // A TEARDOWN, or the end of the connection: the client closed it, or SRS dropped it.
1051	    http_hooks_on_stop();
1052	
1053	    // The player leaves the stats when freed; a client that never played leaves them here.
1054	    srs_freep(player_);
1055	    stat_->on_disconnect(cid_.c_str(), srs_success);
1056	
1057	    // TEARDOWN ends the session (RFC 2326), so its tracks and their networks go with the player: a
1058	    // PLAY after it is not valid until a new DESCRIBE and SETUP, which ask on_play again.
1059	    for (std::map<uint32_t, SrsRtcTrackDescription *>::iterator it = tracks_.begin(); it != tracks_.end(); ++it) {
1060	        SrsRtcTrackDescription *track = it->second;
1060	        SrsRtcTrackDescription *track = it->second;
1061	        srs_freep(track);
1062	    }
1063	    tracks_.clear();
1064	
1065	    for (std::map<uint32_t, ISrsStreamWriter *>::iterator it = networks_.begin(); it != networks_.end(); ++it) {
1066	        ISrsStreamWriter *network = it->second;
1067	        srs_freep(network);
1068	    }
1069	    networks_.clear();
1070	
1071	    return srs_success;
1072	}
