}

// rtspMedias is the media types of a player's session, in order.
func rtspMedias(p *rtsp.Player) string {
	var types []string
	for _, m := range p.Desc.Medias {
		types = append(types, string(m.Type))
	}
	return strings.Join(types, " ")
}

