784	srs_error_t SrsRtspStack::try_consume_rtcp_frame()
785	{
786	    srs_error_t err = srs_success;
787	    char *data = buf_->bytes();
788	
789	    // Check for RTCP over TCP format: $ + channel + length(2 bytes)
790	    if (buf_->length() > 0 && data[0] == '$') {
791	        // Need at least 4 bytes for RTCP over TCP header: $ + channel + length
792	        if (buf_->length() < 4) {
793	            // Not enough data, let caller read more
794	            return srs_error_new(ERROR_RTSP_NEED_MORE_DATA, "need more data for rtcp header");
795	        }
796	
797	
798	        uint8_t channel = (uint8_t)data[1];
799	        uint16_t payload_length = (uint16_t(data[2]) << 8) | uint16_t(data[3]);
800	        int total_frame_size = 4 + payload_length; // 4-byte header + payload
801	
802	        // Check if we have the complete frame
803	        if (buf_->length() < total_frame_size) {
804	            // Not enough data for complete frame, let caller read more
805	            return srs_error_new(ERROR_RTSP_NEED_MORE_DATA, "need more data for complete rtcp frame");
806	        }
807	
808	        // Check if the payload is RTCP (starts at offset 4)
809	        if (payload_length >= 8 && srs_is_rtcp((const uint8_t *)(data + 4), payload_length)) {
810	            // This is an RTCP packet in RTSP over TCP format
811	            srs_trace("RTSP: Consuming RTCP packet(%d), channel=%d, size=%d bytes",
812	                      (uint8_t)data[5], channel, payload_length);
813	            if (rtcp_handler_ && (err = rtcp_handler_->on_rtcp(channel, data + 4, payload_length)) != srs_success) {
814	                return srs_error_wrap(err, "handle rtcp");
815	            }
816	            buf_->erase(total_frame_size);
817	            return srs_success;
818	        } else {
819	            // Unknown interleaved frame, consume it anyway to avoid blocking RTSP parsing
820	            srs_trace("RTSP: Consuming unknown interleaved frame, channel=%d, size=%d bytes",
821	                      channel, payload_length);
822	            buf_->erase(total_frame_size);
823	            return srs_success;
824	        }
825	    }
826	
827	    // Not an interleaved frame (RTP/RTCP over TCP)
828	    return srs_error_new(ERROR_RTSP_TOKEN_NOT_NORMAL, "not interleaved frame");
829	}
